ALTER TABLE ps_product_monthly ADD COLUMN sales_quantity_kind text NOT NULL DEFAULT 'missing' CHECK(sales_quantity_kind IN ('missing','reported','lower_bound','single_variant_estimate'));
ALTER TABLE ps_product_monthly ADD COLUMN child_sales_raw text;
UPDATE ps_product_monthly m SET child_sales_raw=COALESCE(NULLIF(r.raw_data->>'子体销量',''),NULLIF(r.raw_data->>'子体月销量',''),NULLIF(r.raw_data->>'Child Monthly Sales',''),r.normalized_data->>'child_monthly_sales',r.normalized_data->>'monthly_sales'),sales_quantity_kind=CASE WHEN m.sales_scope<>'child' OR m.monthly_sales IS NULL THEN 'missing' WHEN r.normalized_data->>'sales_basis'='single_variant_self_parent' OR (r.raw_data->>'ASIN'=r.raw_data->>'父ASIN' AND r.raw_data->>'变体数'='1' AND COALESCE(r.raw_data->>'子体销量','') IN ('','—','-','N/A')) THEN 'single_variant_estimate' WHEN NULLIF(r.raw_data->>'子体销量','') IS NOT NULL OR COALESCE(r.raw_data->>'子体月销量','') LIKE '%+%' THEN 'lower_bound' ELSE 'reported' END FROM ps_import_rows r WHERE r.tenant_id=m.tenant_id AND r.id=m.source_row_id;
